def table(headers,rows):
 t=doc.add_table(rows=1,cols=len(headers));t.style='Table Grid'
 for c,v in zip(t.rows[0].cells,headers):
  c.text=v
  shade=OxmlElement('w:shd');shade.set(qn('w:fill'),B);c._tc.get_or_add_tcPr().append(shade)
  for paragraph in c.paragraphs:
   for run in paragraph.runs:run.font.color.rgb=DColor.from_string(W);run.font.bold=True
 header=t.rows[0]._tr.get_or_add_trPr();repeat=OxmlElement('w:tblHeader');header.append(repeat)
 for row in rows:
  newrow=t.add_row()
  no_split=OxmlElement('w:cantSplit');newrow._tr.get_or_add_trPr().append(no_split)
  for c,v in zip(newrow.cells,row):c.text=str(v)
 return t
