from docx.text.paragraph import Paragraph
from docx.table import Table
md=[]
for element in doc.element.body.iterchildren():
 if element.tag==qn('w:p'):
  p=Paragraph(element,doc)
  if not p.text.strip():continue
  style_name=p.style.name
  prefix='# ' if style_name=='Title' else '## ' if style_name=='Heading 1' else '### ' if style_name=='Heading 2' else ''
  md.append(prefix+p.text)
 elif element.tag==qn('w:tbl'):
  t=Table(element,doc);rows=[[c.text.replace('|','/').replace('\n','<br>') for c in row.cells] for row in t.rows]
  if rows:
   md.append('| '+' | '.join(rows[0])+' |\n| '+' | '.join('---' for _ in rows[0])+' |\n'+'\n'.join('| '+' | '.join(row)+' |' for row in rows[1:]))
(ROOT/'PMP-Marketing-Department-Owner-Handover-SOP.md').write_text('\n\n'.join(md)+'\n')

