def box(sl,x,y,w,h,fill=W):
 sh=sl.shapes.add_shape(MSO_SHAPE.RECTANGLE,Inches(x),Inches(y),Inches(w),Inches(h));sh.fill.solid();sh.fill.fore_color.rgb=rgb(fill);sh.line.fill.background();return sh
def tx(sl,t,x,y,w,h,size=20,fill=C,bold=False,font='Montserrat'):
 sh=sl.shapes.add_textbox(Inches(x),Inches(y),Inches(w),Inches(h));tf=sh.text_frame;tf.word_wrap=True;tf.margin_left=tf.margin_right=Inches(.02);tf.margin_top=0;tf.margin_bottom=0
 for i,s in enumerate(t.split('\n')):
  p=tf.paragraphs[0] if i==0 else tf.add_paragraph();p.text=s;p.font.name=font;p.font.size=Pt(size);p.font.bold=bold;p.font.color.rgb=rgb(fill);p.space_after=Pt(8)
 return sh
def slide(title,kicker='MARKETING DEPARTMENT / OWNER HANDOVER',dark=False):
 sl=r.slides.add_slide(r.slide_layouts[6]);sl.background.fill.solid();sl.background.fill.fore_color.rgb=rgb(B if dark else P)
 tx(sl,'PMP',.65,.3,1.2,.45,25,W if dark else B,True);tx(sl,kicker,2,.42,12,.3,10,W if dark else B,True)
 box(sl,.7,.95,14.6,.015,W if dark else B);tx(sl,title,.75,1.3,14.5,1,38,W if dark else B,True,'Bebas Neue')
 tx(sl,'MODE OF OPERATIONS • V1.0 • OWNER ACCEPTANCE PENDING',.75,8.5,12,.25,9,W if dark else S);tx(sl,f'{len(r.slides):02d}',14.6,8.45,.65,.3,10,W if dark else B)
 sl.notes_slide.notes_text_frame.text='Owner briefing. The DOCX SOP contains triggers, steps, exit gates and required records. Confirmed workflow derives from user instructions. Proposed controls and unresolved authority remain marked; no live access transfer, owner acceptance or actual client records are implied.'
 return sl
def cards(title,items,dark=False):
 sl=slide(title,dark=dark);n=len(items);cols=2 if n in [2,4] else 3;rows=(n+cols-1)//cols;ww=14.5/cols-.25;hh=5.7/rows-.25
 for i,(head,body) in enumerate(items):
  x=.8+(i%cols)*(ww+.25);y=2.55+(i//cols)*(hh+.25);box(sl,x,y,ww,hh,W);tx(sl,head,x+.22,y+.22,ww-.44,.8,20,B,True);tx(sl,body,x+.22,y+1.2,ww-.44,hh-1.35,17,C)
 return sl
def rowslide(title,rows):
 sl=slide(title);hh=min(1.1,5.6/len(rows))
 for i,(h,b) in enumerate(rows):
  y=2.55+i*hh;box(sl,.8,y,3.7,hh-.13,B);tx(sl,h,.98,y+.16,3.34,hh-.27,14,W,True);tx(sl,b,4.8,y+.1,10.35,hh-.18,17,C)
 return sl
